```apex
public with sharing class AccountScoringJob implements Queueable {

    // Accounts processed per execution.
    private static final Integer CHUNK_SIZE = 200;
    // Maximum chained Queueable depth allowed in a Developer Edition / scratch org.
    private static final Integer MAX_CHAIN_LENGTH = 5;
    // Ids handed to each independent chain started by start().
    private static final Integer SLICE_SIZE = CHUNK_SIZE * MAX_CHAIN_LENGTH; // 1000
    // Synchronous limit on System.enqueueJob calls per transaction.
    private static final Integer MAX_ROOT_JOBS = 50;
    private static final Integer MAX_IDS = SLICE_SIZE * MAX_ROOT_JOBS; // 50,000

    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    /**
     * Starts the scoring run. The Ids are split into independent chains of at most
     * SLICE_SIZE Ids so that no chain exceeds the Queueable stack depth.
     * Returns the Id of the first job enqueued, or null when there is nothing to score.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        if (accountIds.size() > MAX_IDS) {
            throw new IllegalArgumentException(
                'AccountScoringJob supports at most ' + MAX_IDS + ' Ids per run; received ' + accountIds.size()
            );
        }

        Id firstJobId = null;
        for (Integer from = 0; from < accountIds.size(); from += SLICE_SIZE) {
            Integer to = Math.min(from + SLICE_SIZE, accountIds.size());
            List<Id> slice = new List<Id>();
            for (Integer i = from; i < to; i++) {
                slice.add(accountIds[i]);
            }
            Id jobId = System.enqueueJob(new AccountScoringJob(slice));
            if (firstJobId == null) {
                firstJobId = jobId;
            }
        }
        return firstJobId;
    }

    public void execute(QueueableContext context) {
        Integer chunkSize = Math.min(CHUNK_SIZE, accountIds.size());

        List<Id> chunk = new List<Id>();
        for (Integer i = 0; i < chunkSize; i++) {
            chunk.add(accountIds[i]);
        }

        List<Id> remaining = new List<Id>();
        for (Integer i = chunkSize; i < accountIds.size(); i++) {
            remaining.add(accountIds[i]);
        }

        // Exactly one SOQL query and one DML statement for this chunk.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :chunk
        ];

        for (Account acc : accounts) {
            acc.Rating = ratingFor(acc.AnnualRevenue);
        }

        Database.update(accounts, AccessLevel.USER_MODE);

        // Continue the chain with the remaining Ids.
        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= HOT_THRESHOLD) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= WARM_THRESHOLD) {
            return 'Warm';
        }
        return 'Cold';
    }
}
