@IsTest
private class RenewalServiceTest {

    // Original close date and the values the contract derives from it.
    private static final Date CLOSE_DATE = Date.newInstance(2024, 3, 15);
    private static final Date RENEWAL_CLOSE_DATE = Date.newInstance(2025, 3, 15); // +1 year
    private static final Date REMINDER_DATE = Date.newInstance(2025, 1, 14);      // renewal close - 60 days

    // ---------------------------------------------------------------------
    // Test-only selector wrapper
    // ---------------------------------------------------------------------

    // Application.SelectorFactory keys an injected selector by its SObjectType.
    // The ApexMocks stub cannot be stubbed for getSObjectType() through the
    // IOpportunitiesSelector type, so this thin wrapper reports the SObjectType
    // and forwards selectById to the ApexMocks stub. No SOQL is ever executed.
    private class SelectorStub extends fflib_SObjectSelector implements IOpportunitiesSelector {
        private final IOpportunitiesSelector delegate;

        SelectorStub(IOpportunitiesSelector delegate) {
            this.delegate = delegate;
        }

        public Schema.SObjectType getSObjectType() {
            return Opportunity.SObjectType;
        }

        public List<Schema.SObjectField> getSObjectFieldList() {
            return new List<Schema.SObjectField>{
                Opportunity.Id,
                Opportunity.Name,
                Opportunity.AccountId,
                Opportunity.OwnerId,
                Opportunity.StageName,
                Opportunity.CloseDate,
                Opportunity.Amount
            };
        }

        public List<Opportunity> selectById(Set<Id> opportunityIds) {
            return delegate.selectById(opportunityIds);
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Opportunity buildOpportunity(
        Id oppId,
        Id accountId,
        Id ownerId,
        String name,
        String stageName,
        Date closeDate,
        Decimal amount
    ) {
        // In-memory only: no DML.
        return new Opportunity(
            Id = oppId,
            Name = name,
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = stageName,
            CloseDate = closeDate,
            Amount = amount
        );
    }

    private static void mockSelector(fflib_ApexMocks mocks, Set<Id> opportunityIds, List<Opportunity> returned) {
        IOpportunitiesSelector stub = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        mocks.startStubbing();
        mocks.when(stub.selectById(opportunityIds)).thenReturn(returned);
        mocks.stopStubbing();
        Application.Selector.setMock(new SelectorStub(stub));
    }

    private static fflib_ISObjectUnitOfWork mockUnitOfWork(fflib_ApexMocks mocks) {
        fflib_ISObjectUnitOfWork uow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uow);
        return uow;
    }

    // ---------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------

    @IsTest
    static void createRenewals_closedWon_registersRenewalAndLinkedReminder() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        Id oppId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);
        Set<Id> ids = new Set<Id>{ oppId };

        Opportunity won = buildOpportunity(oppId, accountId, ownerId, 'Acme Deal', 'Closed Won', CLOSE_DATE, 100.00);
        mockSelector(mocks, ids, new List<Opportunity>{ won });
        fflib_ISObjectUnitOfWork uow = mockUnitOfWork(mocks);

        RenewalService.createRenewals(ids);

        // Renewal opportunity registered exactly once, with no relation.
        fflib_ArgumentCaptor oppCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).registerNew((SObject) oppCaptor.capture());
        Opportunity renewal = (Opportunity) oppCaptor.getValue();

        System.assertEquals('Acme Deal - Renewal', renewal.Name);
        System.assertEquals(accountId, renewal.AccountId);
        System.assertEquals('Prospecting', renewal.StageName);
        System.assertEquals(RENEWAL_CLOSE_DATE, renewal.CloseDate);
        System.assertEquals(105.00, renewal.Amount);
        System.assertEquals(2, renewal.Amount.scale());

        // Reminder task registered exactly once, related to the new renewal.
        fflib_ArgumentCaptor taskCaptor = fflib_ArgumentCaptor.forClass(Task.class);
        fflib_ArgumentCaptor fieldCaptor = fflib_ArgumentCaptor.forClass(Object.class); // SObjectField token
        fflib_ArgumentCaptor parentCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).registerNew(
