```apex
/**
 * Stages web gifts as NPSP Data Import records (npsp__DataImport__c) and processes them
 * synchronously with NPSP's Data Import Apex API, so NPSP's contact matching, household
 * creation and donation rules apply. Staged records are kept as the audit trail.
 *
 * Result contract:
 *  - One ImportResult per input gift, in input order.
 *  - success is true only when NPSP set npsp__Status__c to 'Imported'.
 *  - A rejected row never stops the other rows; its errorMessage carries NPSP's failure text.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_READY    = 'Ready';
    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1  = 'Contact1';

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // One pre-sized result per input gift, so output order always matches input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
        }

        // 1. Build staging records for non-null gifts, remembering their input index.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();
        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                results[i].errorMessage = 'Gift is null; nothing was imported.';
                continue;
            }
            staged.add(toDataImport(gift));
            stagedIndexes.add(i);
        }
        if (staged.isEmpty()) {
            return results;
        }

        // 2. Insert staging records without all-or-none so one bad row cannot block the rest.
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        List<Integer> toProcessIndexes = new List<Integer>();
        Database.SaveResult[] saves = Database.insert(staged, false);
        for (Integer k = 0; k < saves.size(); k++) {
            Integer idx = stagedIndexes[k];
            if (saves[k].isSuccess()) {
                toProcess.add(staged[k]);
                toProcessIndexes.add(idx);
            } else {
                results[idx].errorMessage = joinErrors(saves[k].getErrors());
            }
        }
        if (toProcess.isEmpty()) {
            return results;
        }

        // 3. Process synchronously with NPSP's Data Import API, using the org's Data Import settings.
        //    The staged records are passed as a List<SObject>, built element by element.
        String processingError = null;
        try {
            List<SObject> dataImports = new List<SObject>();
            for (npsp__DataImport__c di : toProcess) {
                dataImports.add(di);
            }
            npsp.BDI_DataImport_API.processDataImportRecords(
                getDataImportSettings(),
                dataImports,
                false // isDryRun: false, so NPSP commits the imports
            );
        } catch (Exception e) {
            // Keep going: any row NPSP did not import is reported with this message below.
            processingError = e.getMessage();
        }

        // 4. Read back NPSP's results from the staged records.
        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c di : toProcess) {
            stagedIds.add(di.Id);
        }
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedIds
            ]
        );

        // 5. Map NPSP's outcome back to each gift's result.
        for (Integer j = 0; j < toProcess.size(); j++) {
            Integer idx = toProcessIndexes[j];
            ImportResult r = results[idx];
            npsp__DataImport__c row = processed.get(toProcess[j].Id);

            if (row == null) {
                r.success = false;
                r.errorMessage = processingError != null
                    ? processingError
                    : 'The Data Import record could not be read back after NPSP processing.';
                continue;
            }

            r.contactId = row.npsp__Contact1Imported__c;
            r.opportunityId = row.npsp__DonationImported__c;
            r.success = (row.npsp__Status__c == STATUS_IMPORTED);

            if (!r.success) {
                if (String.isNotBlank(row.npsp__FailureInformation__c)) {
                    r.errorMessage = row.npsp__FailureInformation__c;
                } else if (processingError != null) {
                    r.errorMessage = processingError;
                } else {
                    r.errorMessage = 'NPSP did not import this gift (status: '
                        + row.npsp__Status__c + ').';
                }
            }
        }

        return results;
    }

    /** Maps a web gift onto an NPSP Data Import staging record, ready for processing. */
    private static npsp__DataImport__c toDataImport(WebGift gift) {
        return new npsp__DataImport__c(
            npsp__Status__c                  = STATUS_READY,
            npsp__Donation_Donor__c          = DONOR_CONTACT1,
            npsp__Contact1_Firstname__c      = gift.firstName,
            npsp__Contact1_Lastname__c       = gift.lastName,
            npsp__Contact1_Personal_Email__c = gift.email,
            npsp__Donation_Amount__c         = gift.amount,
            npsp__Donation_Date__c           = gift.giftDate
        );
    }

    /** Returns the org's Data Import settings (hierarchy custom setting). */
    private static npsp__Data_Import_Settings__c getDataImportSettings() {
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();
        return settings != null ? settings : new npsp__Data_Import_Settings__c();
    }

    private static String joinErrors(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        for (Database.Error err : errors) {
            messages.add(err.getMessage());
        }
        return messages.isEmpty() ? 'Failed to stage the gift for NPSP import.' : String.join(messages, '; ');
    }
}
