```apex
/**
 * TDTM handler: creates a "Major gift thank-you call" Task when an Opportunity
 * becomes a qualifying major gift (Closed Won and Amount >= 5000).
 *
 * Registration (NPSP Settings > Trigger Configuration > Trigger Handlers):
 *   Class: OPP_MajorGiftFollowUp_TDTM
 *   Object: Opportunity
 *   Trigger Action: AfterInsert;AfterUpdate
 *   Load Order: 5
 *   Asynchronous: false
 *
 * Notes:
 * - Invoked by the NPSP TDTM dispatcher. No Apex trigger is involved, so
 *   activating or deactivating the Trigger Handler record controls execution.
 * - Bulk-safe: no SOQL is needed because every field used (StageName, Amount,
 *   CloseDate, OwnerId, npsp__Primary_Contact__c) is already on the trigger
 *   records. All qualifying tasks are collected and inserted with a single
 *   DML statement issued by this handler. The returned DmlWrapper is empty so
 *   nothing is inserted a second time.
 * - Old and new records are paired by list index, which is how Salesforce
 *   aligns Trigger.old and Trigger.new, so matching does not depend on Ids.
 * - Only transitions into the qualifying state create a task. Edits to a gift
 *   that already qualified do not.
 */
public inherited sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final Integer FOLLOW_UP_DAYS_AFTER_CLOSE = 3;

    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newList == null || newList.isEmpty()) {
            return dmlWrapper;
        }

        // Insert has no prior version of the records; update always does.
        Boolean isUpdate = (oldList != null && !oldList.isEmpty());

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newList.size(); i++) {
            Opportunity newOpp = (Opportunity) newList[i];

            if (!isQualifyingMajorGift(newOpp)) {
                continue;
            }

            Boolean createTask = true;

            if (isUpdate) {
                // Create only when the opportunity transitions into the qualifying state.
                Opportunity oldOpp = (i < oldList.size()) ? (Opportunity) oldList[i] : null;
                createTask = (oldOpp != null && !isQualifyingMajorGift(oldOpp));
            }

            if (createTask) {
                tasksToInsert.add(buildFollowUpTask(newOpp));
            }
        }

        // Single DML for the whole batch, issued by this handler.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private static Boolean isQualifyingMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Date dueDate = (opp.CloseDate == null)
            ? null
            : opp.CloseDate.addDays(FOLLOW_UP_DAYS_AFTER_CLOSE);

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = dueDate
        );
    }
}
