```apex
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Ids collected since the last drain. Static because the trigger runs once per chunk
    // (for example 200 + 50 for a 250-row insert) and every chunk must add to the same set.
    private static Set<Id> pendingIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null) {
            return;
        }
        for (SObject record : triggerNew) {
            if (record.Id != null) {
                pendingIds.add(record.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerOld == null) {
            return;
        }

        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject oldRecord : triggerOld) {
            if (oldRecord.Id != null) {
                oldById.put(oldRecord.Id, (Opportunity) oldRecord);
            }
        }

        for (SObject newRecord : triggerNew) {
            Opportunity newOpp = (Opportunity) newRecord;
            if (newOpp.Id == null) {
                continue;
            }
            Opportunity oldOpp = oldById.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }
            // StageName is required on Opportunity, so a null value means the field was not part of this DML.
            if (newOpp.StageName != null && newOpp.StageName != oldOpp.StageName) {
                pendingIds.add(newOpp.Id);
            }
        }
    }

    // Returns the Ids collected since the last drain and clears the set.
    // Called by OpportunityErpSyncFinalizer at the end of each DML operation.
    public static Set<Id> drainPendingIds() {
        Set<Id> ids = new Set<Id>();
